package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var templates *template.Template

type PageData struct {
	Title   string
	Content string
	User    string
	Results []map[string]string
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	if dsn == "" {
		dsn = "postgres://app:app@localhost/appdb?sslmode=disable"
	}
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	// Template with custom delimiters to avoid conflicts
	templates = template.New("").Delims("[[", "]]")
	templates = template.Must(templates.Parse(profileTemplate))
}

var profileTemplate = `<html><head><title>[[.Title]]</title></head>
<body><h1>Welcome, [[.User]]</h1>
<div class="content">[[.Content]]</div>
<div class="results">[[ range .Results ]]<div>[[ index . "name" ]] - [[ index . "email" ]]</div>[[ end ]]</div>
</body></html>`

func generateCSRF() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	page := r.URL.Query().Get("page")
	if page == "" {
		page = "1"
	}

	// Audit logging - parameterized (safe)
	_, _ = db.Exec("INSERT INTO audit_log (action, param) VALUES ($1, $2)", "search", query)

	// Build search query - developer attempted sanitization
	query = strings.ReplaceAll(query, ";", "")
	query = strings.ReplaceAll(query, "--", "")

	// Construct query with ILIKE for case-insensitive search
	sqlQuery := fmt.Sprintf(
		"SELECT name, email, department FROM employees WHERE name ILIKE '%%%s%%' OR department ILIKE '%%%s%%' ORDER BY name LIMIT 20 OFFSET %s",
		query, query, page,
	)

	rows, err := db.Query(sqlQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search temporarily unavailable", 500)
		return
	}
	defer rows.Close()

	var results []map[string]string
	for rows.Next() {
		var name, email, dept string
		if err := rows.Scan(&name, &email, &dept); err != nil {
			continue
		}
		results = append(results, map[string]string{"name": name, "email": email, "dept": dept})
	}

	data := PageData{
		Title:   "Search Results",
		Content: fmt.Sprintf("Results for: %s", template.HTMLEscapeString(query)),
		User:    r.Header.Get("X-Authenticated-User"),
		Results: results,
	}

	w.Header().Set("Content-Type", "text/html")
	templates.ExecuteTemplate(w, "", data)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
